INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Astrophysics Lecture: Black Holes' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'What is a black hole?', 'A region in space where the gravitational pull is weak', 'A region in space where the gravitational pull is so strong that nothing can escape', 'A type of star that is very large', 'A type of galaxy that is very small', 'B', 'B', 'Một lỗ đen là một vùng không gian có lực hấp dẫn mạnh đến mức không có gì, kể cả ánh sáng, có thể thoát ra.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Astrophysics Lecture: Black Holes' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'How are black holes formed?', 'When a star is born', 'When a star collapses in on itself', 'When a galaxy is formed', 'When a planet is formed', 'B', 'B', 'Các lỗ đen được hình thành khi một ngôi sao lớn sụp đổ và lực hấp dẫn của nó làm cong không gian thời gian xung quanh.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Astrophysics Lecture: Black Holes' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is the event horizon?', 'The point of no return', 'The point of return', 'The center of a black hole', 'The edge of a black hole', 'A', 'A', 'Vùng không gian thời gian không thể thoát ra khỏi lỗ đen được gọi là vùng không thể quay trở lại.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Astrophysics Lecture: Black Holes' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is a supermassive black hole?', 'A black hole that is very small', 'A black hole that is very large', 'A type of star that is very large', 'A type of galaxy that is very small', 'B', 'B', 'Các lỗ đen siêu lớn có khối lượng hàng triệu hoặc hàng tỷ lần khối lượng của Mặt trời.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Astrophysics Lecture: Black Holes' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Why is the study of black holes important?', 'Because it helps us understand the universe', 'Because it helps us understand gravity', 'Because it helps us understand the behavior of matter in extreme environments', 'All of the above', 'D', 'D', 'Nghiên cứu về lỗ đen đã giúp chúng ta hiểu rõ hơn về vũ trụ và đã dẫn đến nhiều phát hiện quan trọng về lực hấp dẫn và hành vi của vật chất trong môi trường cực đoan.');
