INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'AI Ethics in the Age of Automation' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Tại sao chúng ta cần phải tăng cường tính minh bạch khi triển khai trí tuệ nhân tạo?', 'Vì chúng ta cần phải hiểu được cách trí tuệ nhân tạo đưa ra quyết định', 'Vì chúng ta cần phải loại bỏ thiên vị trong quyết định của trí tuệ nhân tạo', 'Vì chúng ta cần phải xem xét tác động xã hội của tự động hóa', 'Vì chúng ta cần phải tăng cường tính minh bạch', 'A', 'A', 'Chúng ta cần phải tăng cường tính minh bạch khi triển khai trí tuệ nhân tạo vì chúng ta cần phải hiểu được cách trí tuệ nhân tạo đưa ra quyết định.');
