INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Debriefing a Complex Engineering Project' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'Chi phí dự án Mars Rover đã vượt quá ngân sách bao nhiêu?', '5%', '10%', '15%', '20%', 'C', 'C', 'Chi phí dự án đã vượt quá ngân sách 15% do các vấn đề kỹ thuật không thể dự đoán trước.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Debriefing a Complex Engineering Project' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'Kế hoạch dự phòng là gì?', 'Kế hoạch dự phòng là kế hoạch dự phòng cho các vấn đề kỹ thuật không thể dự đoán trước.', 'Kế hoạch dự phòng là kế hoạch dự phòng cho các vấn đề tài chính.', 'Kế hoạch dự phòng là kế hoạch dự phòng cho các vấn đề nhân sự.', 'Kế hoạch dự phòng là kế hoạch dự phòng cho các vấn đề kỹ thuật và tài chính.', 'D', 'D', 'Kế hoạch dự phòng là kế hoạch dự phòng cho các vấn đề kỹ thuật và tài chính.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Debriefing a Complex Engineering Project' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'Dự án Mars Rover đã đạt được thành công như thế nào?', 'Dự án đã đạt được thành công hoàn toàn.', 'Dự án đã đạt được thành công một phần.', 'Dự án đã không đạt được thành công.', 'Dự án đã đạt được thành công nhưng có một số vấn đề.', 'D', 'D', 'Dự án đã đạt được thành công nhưng có một số vấn đề.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Debriefing a Complex Engineering Project' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Lời khuyên cuối cùng của Lisa là gì?', 'Lời khuyên cuối cùng của Lisa là chúng ta nên được tích cực hơn trong việc giải quyết các vấn đề.', 'Lời khuyên cuối cùng của Lisa là chúng ta nên được tích cực hơn trong việc dự đoán các vấn đề.', 'Lời khuyên cuối cùng của Lisa là chúng ta nên được tích cực hơn trong việc giải quyết các vấn đề và dự đoán các vấn đề.', 'Lời khuyên cuối cùng của Lisa là chúng ta nên được tích cực hơn trong việc dự đoán các vấn đề và giải quyết các vấn đề.', 'C', 'C', 'Lời khuyên cuối cùng của Lisa là chúng ta nên được tích cực hơn trong việc giải quyết các vấn đề và dự đoán các vấn đề.');
INSERT INTO study_contents (type, title, category, body_text, media_url, description, duration, questions_count) VALUES ('LISTENING', 'Cultural Assimilation: A Nuanced Debate', 'C1', 'Transcript:
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Cultural Assimilation: A Nuanced Debate' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'Theo John, lợi ích của sự hòa nhập văn hóa bao gồm:', 'Sự đồng nhất hóa văn hóa', 'Trao đổi văn hóa và hiểu biết', 'Sự mất mát văn hóa độc đáo', 'Sự bất đồng về văn hóa', 'B', 'B', 'John cho rằng sự hòa nhập văn hóa mang lại lợi ích về trao đổi văn hóa và hiểu biết.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Cultural Assimilation: A Nuanced Debate' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'Theo Lisa, giáo dục có thể đóng vai trò gì trong sự hòa nhập văn hóa?', 'Giáo dục có thể thúc đẩy sự hòa nhập văn hóa', 'Giáo dục có thể thúc đẩy sự hiểu biết và trao đổi văn hóa', 'Giáo dục không có vai trò gì trong sự hòa nhập văn hóa', 'Giáo dục có thể gây ra sự mất mát văn hóa', 'B', 'B', 'Lisa cho rằng giáo dục có thể thúc đẩy sự hiểu biết và trao đổi văn hóa.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Cultural Assimilation: A Nuanced Debate' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'Theo John, chìa khóa để tìm được sự cân bằng giữa trao đổi văn hóa và bảo tồn văn hóa là:', 'Sự đồng nhất hóa văn hóa', 'Sự tôn trọng văn hóa', 'Sự mất mát văn hóa', 'Sự bất đồng về văn hóa', 'B', 'B', 'John cho rằng sự tôn trọng văn hóa là chìa khóa để tìm được sự cân bằng giữa trao đổi văn hóa và bảo tồn văn hóa.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Cultural Assimilation: A Nuanced Debate' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'Theo Lisa, sự hòa nhập văn hóa không chỉ liên quan đến các cá nhân mà còn liên quan đến:', 'Các chính phủ và tổ chức', 'Các cá nhân và tổ chức', 'Các chính phủ và cá nhân', 'Các tổ chức và cá nhân', 'A', 'A', 'Lisa cho rằng sự hòa nhập văn hóa liên quan đến các chính phủ và tổ chức.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('LISTENING', (SELECT id FROM study_contents WHERE type = 'LISTENING' AND title = 'Cultural Assimilation: A Nuanced Debate' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Theo John, chính sách và chương trình nào có thể thúc đẩy sự đa dạng văn hóa và sự hiểu biết?', 'Chính sách và chương trình thúc đẩy sự đồng nhất hóa văn hóa', 'Chính sách và chương trình thúc đẩy sự đa dạng văn hóa và sự hiểu biết', 'Chính sách và chương trình không có vai trò gì trong sự đa dạng văn hóa', 'Chính sách và chương trình gây ra sự mất mát văn hóa', 'B', 'B', 'John cho rằng chính sách và chương trình thúc đẩy sự đa dạng văn hóa và sự hiểu biết.');
